<?php
defined('ABSPATH')||exit;final class SPL_Admin{public function hooks(){add_action('admin_menu',array($this,'menu'));add_action('admin_post_spl_review',array($this,'review'));add_action('admin_post_spl_report',array($this,'report'));add_action('admin_notices',array($this,'notice'));}public function menu(){add_menu_page('PDF Library Management','PDF Library Management','manage_pdf_library','pdf-library-management',array($this,'page'),'dashicons-book-alt',32);add_submenu_page('pdf-library-management','Reports','Reports','manage_pdf_library','pdf-library-reports',array($this,'reports'));}public function page(){$items=get_posts(array('post_type'=>SPL_Helpers::TYPE,'post_status'=>array('pending','publish','draft','private'),'posts_per_page'=>250));?><div class="wrap"><h1>PDF Library Management</h1><table class="widefat striped"><?php foreach($items as$i):?><tr><td><strong><?php echo esc_html($i->post_title);?></strong><br><?php echo esc_html(SPL_Helpers::term($i->ID,SPL_Helpers::DOCTYPE));?></td><td><?php echo esc_html(get_post_status($i));?></td><td><form action="<?php echo esc_url(admin_url('admin-post.php'));?>" method="post"><input type="hidden" name="action" value="spl_review"><input type="hidden" name="id" value="<?php echo absint($i->ID);?>"><?php wp_nonce_field('spl_review_'.$i->ID);?><select name="decision"><option value="publish">Approve</option><option value="draft">Reject</option><option value="private">Hide</option><option value="feature">Toggle Featured</option></select><textarea name="note" placeholder="Copyright and safety review note"></textarea><button>Apply</button></form></td></tr><?php endforeach;?></table></div><?php }public function review(){if(!current_user_can('manage_pdf_library'))wp_die('Denied');$id=absint($_POST['id']??0);check_admin_referer('spl_review_'.$id);$d=sanitize_key(wp_unslash($_POST['decision']??''));if('feature'===$d)update_post_meta($id,'_spl_featured','1'===SPL_Helpers::meta($id,'featured','0')?'0':'1');elseif(in_array($d,array('publish','draft','private'),true))wp_update_post(array('ID'=>$id,'post_status'=>$d));wp_safe_redirect(admin_url('admin.php?page=pdf-library-management'));exit;}public function reports(){global$wpdb;$rows=$wpdb->get_results("SELECT * FROM {$wpdb->prefix}spl_reports ORDER BY created_at DESC LIMIT 250");?><div class="wrap"><h1>Library Reports</h1><table class="widefat"><?php foreach($rows as$r):?><tr><td><?php echo esc_html(get_the_title($r->document_id));?></td><td><?php echo esc_html($r->reason);?><br><?php echo esc_html($r->details);?></td><td><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="spl_report"><input type="hidden" name="id" value="<?php echo absint($r->id);?>"><?php wp_nonce_field('spl_report_'.$r->id);?><select name="status"><option>open</option><option>reviewing</option><option>resolved</option><option>dismissed</option></select><button>Save</button></form></td></tr><?php endforeach;?></table></div><?php }public function report(){if(!current_user_can('manage_pdf_library'))wp_die('Denied');$id=absint($_POST['id']??0);check_admin_referer('spl_report_'.$id);$s=sanitize_key(wp_unslash($_POST['status']??''));if(!in_array($s,array('open','reviewing','resolved','dismissed'),true))wp_die('Invalid');global$wpdb;$wpdb->update($wpdb->prefix.'spl_reports',array('status'=>$s),array('id'=>$id));wp_safe_redirect(admin_url('admin.php?page=pdf-library-reports'));exit;}public function notice(){if(current_user_can('activate_plugins')&&get_transient('spl_notice')){delete_transient('spl_notice');echo'<div class="notice notice-success"><p>PDF Library is active.</p></div>';}}}

